-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `top_20_juegos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `top_20_juegos` AS select `videojuegos`.`nombre` AS `juego`,`plataforma`.`nombre` AS `plataforma`,`ventas`.`ventasGB` AS `ventasGB` from ((`videojuegos` join `plataforma` on(`videojuegos`.`id_plataforma` = `plataforma`.`id`)) join `ventas` on(`ventas`.`id_videojuego` = `videojuegos`.`id`)) order by `ventas`.`ventasGB` desc limit 20
;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `ventas_globales_plataforma`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `ventas_globales_plataforma` AS select `plataforma`.`nombre` AS `plataforma`,sum(`ventas`.`ventasGB`) AS `total_ventas` from ((`plataforma` join `videojuegos` on(`videojuegos`.`id_plataforma` = `plataforma`.`id`)) join `ventas` on(`ventas`.`id_videojuego` = `videojuegos`.`id`)) group by `plataforma`.`nombre` order by sum(`ventas`.`ventasGB`) desc
;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `videojuegos_misc`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `videojuegos_misc` AS select `j`.`nombre` AS `nombre`,`j`.`id_genero` AS `id_genero`,`v`.`ventasGB` AS `ventasGB` from (`videojuegos` `j` join `ventas` `v`) where `j`.`id` = `v`.`id_videojuego` and `j`.`id_genero` = 6
;

